-- Execute antes: createdb ceuma_semana16
-- Depois execute os arquivos com psql -d ceuma_semana16.
CREATE SCHEMA IF NOT EXISTS semana16;
SET search_path TO semana16;
CREATE TABLE IF NOT EXISTS cliente (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome text NOT NULL, email text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS produto (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome text NOT NULL, sku text NOT NULL UNIQUE, preco numeric(12,2) NOT NULL CHECK(preco>=0), estoque integer NOT NULL CHECK(estoque>=0));
CREATE TABLE IF NOT EXISTS pedido (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, cliente_id bigint NOT NULL REFERENCES cliente(id), criado_em timestamptz NOT NULL DEFAULT now(), status text NOT NULL CHECK(status IN ('criado','pago','cancelado')));
CREATE TABLE IF NOT EXISTS item_pedido (pedido_id bigint REFERENCES pedido(id), produto_id bigint REFERENCES produto(id), quantidade integer NOT NULL CHECK(quantidade>0), preco_unitario numeric(12,2) NOT NULL CHECK(preco_unitario>=0), PRIMARY KEY(pedido_id,produto_id));
